MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M t USING (SELECT 'BizTypeByDivision' AS SQL_ID, 'CM' AS MDU_DIVS_CD, 'Biz Type by Division (BIZ_TYPE_BPMS)' AS SQL_NM, 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''BIZ_TYPE_BPMS'' ORDER BY DISPLAY_SEQ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-07-01 14:39:29','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-01 14:39:29','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
ON (t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET t.SQL_NM = s.SQL_NM, t.SQL_DTL_CTN = s.SQL_DTL_CTN, t.USE_YN = s.USE_YN, t.CREATED_BY = s.CREATED_BY, t.CREATION_DATE = s.CREATION_DATE, t.LAST_UPDATED_BY = s.LAST_UPDATED_BY, t.LAST_UPDATE_DATE = s.LAST_UPDATE_DATE
